import {escapeHtml as h,number} from './domain.js';
import {planetArt,badge,shipArt} from './art.js';
const units=[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']];
const hasAllies=group=>units.some(([key])=>Number(group?.before?.[key])>0||Number(group?.after?.[key])>0);
const date=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
function sideTable(title,group,tone,race='elys'){
 const before=group?.before,after=group?.after;
 const known=before&&after,engaged=units.reduce((n,[k])=>n+Number(before?.[k]||0),0),lost=known?units.reduce((n,[k])=>n+Math.max(0,Number(before[k]||0)-Number(after[k]||0)),0):0;
 const percent=engaged?Math.round(lost/engaged*100):0;
 return `<section class="report-side ${tone}"><h3>${title}</h3>${known?`<div class="report-tally ${lost?'has-losses':''}"><span><b>${number(engaged-lost)}</b> survivants</span><span><b>${lost?'−':''}${number(lost)}</b> pertes · ${percent} %</span><progress value="${engaged-lost}" max="${engaged||1}" aria-label="Forces survivantes"></progress></div>`:''}<table><thead><tr><th>Unités</th><th>Engagées</th><th>Restantes</th><th>Pertes</th></tr></thead><tbody>${units.map(([k,label])=>{const loss=before?.[k]==null||after?.[k]==null?null:Math.max(0,before[k]-after[k]);return `<tr class="${loss?'has-losses':''}"><th>${k==='soldiers'?badge('race',race):shipArt(race,k==='scouts'?'scout':k==='bombers'?'bomber':'fighter')}<span>${label}</span></th><td>${before?.[k]==null?'—':number(before[k])}</td><td class="${loss?'remaining-hit':''}">${after?.[k]==null?'—':number(after[k])}</td><td class="casualty ${loss?'loss-hit':''}">${loss==null?'—':loss?`−${number(loss)}`:'0'}</td></tr>`;}).join('')}</tbody></table>${!before?.soldiers&&before?.soldiers!==0?'<small>Forces au sol non observées.</small>':''}${!after?'<small>Pertes non enregistrées dans cet ancien rapport.</small>':''}</section>`;
}
export function reportCard(r,unreadIds=[]){
 const d=r.details||{},s=d.sides,appearance=planetArt(r.appearance,true),race=String(r.appearance||'elys').split('_')[0];
 const combat=['battle','capture'].includes(r.event);
 const body=combat?`<p class="report-outcome">${d.captured?'Planète conquise':d.mission==='attack'?'Vos forces en attaque':'Vos forces en défense'}</p>${d.opponents?.length?`<div class="report-opponents">${d.opponents.map(o=>`<span>${badge('race',o.race)}<b>${h(o.name)}</b>${o.origin?` · ${h(o.origin)}`:''}</span>`).join('')}</div>`:''}<div class="report-camps"><div class="report-friendly">${sideTable('Vos forces',s?.own||{before:d.before,after:d.after},'own',race)}${hasAllies(s?.allies)?sideTable('Forces alliées',s.allies,'allied',race):''}</div><div class="report-opposition">${sideTable('Forces ennemies',s?.enemies||{before:{...d.enemy_space,soldiers:d.enemy_ground}},'hostile',race)}</div></div>`:r.event==='takeover'?`<p>Nouveau propriétaire : ${h(d.new_owner||'Inconnu')}.</p>`:`<p>${h(d.fleet||'Renforts')} a rejoint ce monde en ${d.mission==='attack'?'attaque':'défense'}.${d.teleport?' Soldats indisponibles pendant une heure.':d.lands_at?` Débarquement après ${date(d.lands_at)}.`:''}</p>`;
 return `<details class="battle-report visual-report ${unreadIds.includes(r.id)?'is-unread':''}"><summary>${appearance?`<img class="report-world" src="${appearance}" alt="" width="44" height="44">`:''}<span class="report-event ${h(r.event)}">${({capture:'Conquête',arrival:'Arrivée',battle:'Combat',takeover:'Prise de contrôle'})[r.event]||'Opération'}</span><b>${h(r.planet||'Planète')}</b><time datetime="${h(r.occurred_at)}">${date(r.occurred_at)}</time></summary><div class="report-body">${body}</div></details>`;
}
export function battleReportsView(data,unreadIds=[],history={}){
 const page=history.response||data?.report_page,items=page?.items||(data?.reports||[]).filter(r=>['battle','capture','arrival','takeover'].includes(r.event)).slice(0,15);
 return `<section class="battle-reports"><div class="military-section-heading"><div><span class="eyebrow">JOURNAL DES OPÉRATIONS</span><h2>Rapports de bataille</h2></div><span>Page ${Number(history.page)||1}</span></div>${history.error?`<p class="form-error" role="alert">${h(history.error)}</p>`:''}${items.length?items.map(r=>reportCard(r,unreadIds)).join(''):'<p class="empty">Aucun engagement signalé.</p>'}<nav class="report-pagination" aria-label="Pages des rapports"><button class="secondary" data-report-page="previous" ${!history.stack?.length||history.loading?'disabled':''}>← Précédents</button><span>${items.length} rapport${items.length>1?'s':''}</span><button class="secondary" data-report-page="next" ${!page?.has_more||history.loading?'disabled':''}>Suivants →</button></nav></section>`;
}
export function recentBattlesView(data){const reports=data?.recent_battles||(data?.reports||[]).filter(r=>['battle','capture'].includes(r.event)).slice(0,5);return `<section class="battle-reports recent-battles"><div class="military-section-heading"><h2>Derniers combats</h2><button class="text-button" data-page="alerts">Tous les rapports →</button></div>${reports.length?reports.map(r=>reportCard(r)).join(''):'<p class="empty">Aucun combat enregistré.</p>'}</section>`;}
